import { Controller, Put, Param, Body, UseGuards } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { RolesGuard } from '../guards/roles.guard';
import { Roles } from '../decorators/roles.decorator';
import { AdminService } from './admin.service';
import { ProductValidationDto } from './dto/product-validation.dto';

@Controller('admin')
@UseGuards(AuthGuard('jwt'), RolesGuard)
export class AdminController {
  constructor(private readonly adminService: AdminService) {}

  @Put('products/:id/validate')
  @Roles('admin')
  async validateProduct(@Param('id') id: string) {
    return this.adminService.validateProduct(id);
  }

  @Put('products/:id/reject')
  @Roles('admin')
  async rejectProduct(
    @Param('id') id: string,
    @Body() rejectDto: ProductValidationDto
  ) {
    return this.adminService.rejectProduct(id, rejectDto.reason);
  }
}
